hooks.command:
python3 -c "
import sys, json, os, subprocess
try:
    data = json.load(sys.stdin)
    f = data.get('file_path', '')
except:
    sys.exit(0)
if f.endswith('.go'):
    subprocess.run(['goimports', '-w', f], capture_output=True)
    subprocess.run(['gofmt', '-w', f], capture_output=True)
elif f.endswith('.py'):
    subprocess.run(['ruff', 'format', f], capture_output=True)
"
